    q: tr("\u0645\u0646 \u062A\u0648\u06CC \u0647\u0648\u06A9 \u0645\u0634\u06A9\u0644 \u062F\u0627\u0631\u0645!"),
    a: tr("\u0642\u062F\u0631\u062A \u0647\u0648\u06A9 \u0627\u0632 \u0686\u0631\u062E\u0634 \u06A9\u0645\u0631 \u0648 \u0644\u06AF\u0646 \u0645\u06CC\u0627\u062F\u060C \u0646\u0647 \u0641\u0642\u0637 \u062F\u0633\u062A. \u0622\u0631\u0646\u062C\u062A \u0631\u0648 \u0632\u0627\u0648\u06CC\u0647\u200C\u06CC \u062B\u0627\u0628\u062A (\u062A\u0642\u0631\u06CC\u0628\u0627\u064B \u06F9\u06F0 \u062F\u0631\u062C\u0647) \u0646\u06AF\u0647 \u062F\u0627\u0631 \u0648 \u0628\u0630\u0627\u0631 \u0686\u0631\u062E\u0634 \u0628\u062F\u0646 \u062F\u0633\u062A\u062A \u0631\u0648 \u0628\u0627 \u062E\u0648\u062F\u0634 \u0628\u06CC\u0627\u0631\u0647.")
